import test from 'node:test';
import assert from 'node:assert/strict';
import { compileRequiredFields, CONTRACT } from './shared/required-fields.mjs';
import { orderChecksBefore, orderChecksAfter, orderNeedsApproval } from './projects/order.mjs';
import { invoiceChecksBefore, invoiceChecksAfter, invoiceNeedsApproval } from './projects/invoice.mjs';

// A separate, intentionally minimal evaluator is used only for the fixture.
// It is not generated by the shared generator, and is not TEI runtime evidence.
function evaluate(plan, record) {
  const diagnostics = [];
  if (plan.format !== 'tei.reference.validation-plan/v0' || !Array.isArray(plan.rules)) {
    throw new Error('INVALID_PLAN');
  }
  for (const { op, field } of plan.rules) {
    if (op === 'required-text') {
      if (typeof record[field] !== 'string' || record[field].trim() === '') {
        diagnostics.push(field + ':required-text');
      }
    } else if (op === 'nonnegative-safe-integer') {
      if (!Number.isSafeInteger(record[field]) || record[field] < 0) {
        diagnostics.push(field + ':nonnegative-safe-integer');
      }
    } else {
      throw new Error('UNSUPPORTED_OPERATOR');
    }
  }
  return diagnostics;
}

const expectedOrder = {
  format: 'tei.reference.validation-plan/v0',
  rules: [
    { op: 'required-text', field: 'orderId' },
    { op: 'nonnegative-safe-integer', field: 'totalYen' },
  ],
};
const expectedInvoice = {
  format: 'tei.reference.validation-plan/v0',
  rules: [
    { op: 'required-text', field: 'invoiceId' },
    { op: 'nonnegative-safe-integer', field: 'amountYen' },
  ],
};

for (const { name, before, after, expected, cases } of [
  {
    name: 'order', before: orderChecksBefore, after: orderChecksAfter, expected: expectedOrder,
    cases: [
      [{ orderId: 'O-1', totalYen: 0 }, []],
      [{ orderId: '  ', totalYen: 25 }, ['orderId:required-text']],
      [{ orderId: 'O-1', totalYen: -1 }, ['totalYen:nonnegative-safe-integer']],
      [{ orderId: 'O-1', totalYen: '25' }, ['totalYen:nonnegative-safe-integer']],
      [{ orderId: 'O-1', totalYen: Number.MAX_SAFE_INTEGER + 1 }, ['totalYen:nonnegative-safe-integer']],
    ],
  },
  {
    name: 'invoice', before: invoiceChecksBefore, after: invoiceChecksAfter, expected: expectedInvoice,
    cases: [
      [{ invoiceId: 'I-1', amountYen: 15 }, []],
      [{ invoiceId: null, amountYen: 0 }, ['invoiceId:required-text']],
      [{ invoiceId: 'I-1', amountYen: null }, ['amountYen:nonnegative-safe-integer']],
      [{ invoiceId: 'I-1', amountYen: 1.5 }, ['amountYen:nonnegative-safe-integer']],
      [{ invoiceId: '  ', amountYen: -1 }, ['invoiceId:required-text', 'amountYen:nonnegative-safe-integer']],
    ],
  },
]) {
  test(name + ': extraction preserves exact generated plan and independent golden', () => {
    assert.deepStrictEqual(before(), expected);
    assert.deepStrictEqual(after(), expected);
    assert.equal(JSON.stringify(after()), JSON.stringify(before()));
    assert.equal(JSON.stringify(after()), JSON.stringify(after()));
  });
  for (const [record, expectedDiagnostics] of cases) {
    test(name + ': independently specified behavior ' + JSON.stringify(record), () => {
      assert.deepStrictEqual(evaluate(before(), record), expectedDiagnostics);
      assert.deepStrictEqual(evaluate(after(), record), expectedDiagnostics);
    });
  }
}

test('shared generator rejects ambiguous or different semantics', () => {
  const valid = { identityField: 'orderId', amountField: 'totalYen', contract: CONTRACT };
  assert.throws(() => compileRequiredFields({ ...valid, contract: 'nullable-amount/v1' }), /UNSUPPORTED_SEMANTICS/);
  assert.throws(() => compileRequiredFields({ ...valid, identityField: '../outside' }), /INVALID_FIELD/);
  assert.throws(() => compileRequiredFields({ ...valid, amountField: 'orderId' }), /CONFLICTING_FIELDS/);
  assert.throws(() => compileRequiredFields({ ...valid, identityField: undefined }), /INVALID_FIELD/);
  assert.throws(() => compileRequiredFields(), /UNSUPPORTED_SEMANTICS/);
});

test('validation plans do not absorb differing approval rules', () => {
  assert.deepStrictEqual(orderChecksAfter().rules.map(r => r.op), invoiceChecksAfter().rules.map(r => r.op));
  assert.equal(orderNeedsApproval({ totalYen: 90_000 }), false);
  assert.equal(orderNeedsApproval({ totalYen: 100_000 }), true);
  assert.equal(invoiceNeedsApproval({ amountYen: 70_000, overseas: false }), false);
  assert.equal(invoiceNeedsApproval({ amountYen: 49_999, overseas: true }), false);
  assert.equal(invoiceNeedsApproval({ amountYen: 50_000, overseas: true }), true);
});

test('unsupported operations are not quietly treated as success', () => {
  assert.throws(
    () => evaluate({ format: expectedOrder.format, rules: [{ op: 'unknown', field: 'orderId' }] }, { orderId: 'O-1' }),
    /UNSUPPORTED_OPERATOR/,
  );
});
